#include <iostream>
using namespace std;

class Buffer {
    int* data_;
    int size_;

public:
    Buffer(int size) : data_(new int[size]), size_(size) {
        cout << "made " << size_ << endl;
    }
    ~Buffer() {
        delete[] data_;
        cout << "freed" << endl;
    }
};

int main() {
    Buffer b(4);
    cout << "using it" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Tag {
    string name_;

public:
    Tag(string name) : name_(name) { cout << "hello " << name_ << endl; }
    ~Tag() { cout << "bye " << name_ << endl; }
};

int main() {
    Tag a("A");
    Tag b("B");
    Tag c("C");
    return 0;
}

